// @FIGURE_CODE_BEGIN
var container = document.getElementById('container');
var draw = SVG().addTo(container).size('100%', '100%');
var W = 720, H = 460;
draw.viewbox(0, 0, W, H);

/* ── Constants & state ─────────────────────────────────────────────────── */
var PCX = 170, PCY = 100, PR = 62;          // pulley center & radius
var BLOCK = 62;                              // main block side length
var CX1 = PCX - PR, CX2 = PCX + PR;          // cord x / block centers
var BASE1 = 205, BASE2 = 276;                // resting block tops (m1 higher)
var M1 = 1;                                  // fixed lighter mass
var TRAVEL = 55;                             // max one-way travel of blocks
var RED = '#c0392b', GREEN = '#1e8e5a', CORDC = '#e7c469';
var FBS = 78, FBX1 = 498, FBX2 = 648, FBCY = 176; // free-body squares

var m2Mass = 3, releaseState = 'held', offset = 0, vel = 0;
var animId = null, lastT = 0;
var STATES = ['held', 'released', 'moving'];

/* ── Small helpers ─────────────────────────────────────────────────────── */
function tip(t) { return function (e) { showTooltip(t, e); }; }
function pop(title, body) { return function () { showPopup(title, body); }; }
function interactive(el, t, title, body) {
  el.css('cursor', 'pointer')
    .on('mousemove', tip(t))
    .on('mouseleave', hideTooltip)
    .on('click', pop(title, body));
}
function aMag() { return Math.abs(m2Mass - M1) / (m2Mass + M1); }

/* Arrow (line + filled head) inside a group, returns the group */
function makeArrow(parent, x1, y1, x2, y2, color, w) {
  var g = parent.group();
  var len = Math.hypot(x2 - x1, y2 - y1);
  if (len < 1) return g;
  var ux = (x2 - x1) / len, uy = (y2 - y1) / len;
  var px = -uy, py = ux, s = 6 + w;
  g.line(x1, y1, x2, y2).stroke({ color: color, width: w, linecap: 'round' });
  g.polygon([
    [x2, y2],
    [x2 - ux * s + px * 4.2, y2 - uy * s + py * 4.2],
    [x2 - ux * s - px * 4.2, y2 - uy * s - py * 4.2]
  ]).fill(color);
  return g;
}
function labelText(parent, txt, x, y, anchor, size, fill) {
  return parent.text(txt)
    .font({ family: 'Georgia, "Times New Roman", serif', size: size || 15, style: 'italic' })
    .attr({ 'text-anchor': anchor || 'middle' })
    .fill(fill || '#333')
    .move(x, y - (size || 15) / 2);
}
/* Vector label: glyph with a small arrow drawn over it (T⃗, w⃗₁ …) */
function vectorLabel(parent, glyph, sub, x, y, anchor, size, fill) {
  size = size || 15;
  fill = fill || '#1a1a1a';
  var g = parent.group();
  var t = g.text(function (add) {
    add.tspan(glyph);
    if (sub) add.tspan(sub).attr({ 'font-size': size * 0.68, 'baseline-shift': 'sub', dy: size * 0.28 });
  })
    .font({ family: 'Georgia, "Times New Roman", serif', size: size, style: 'italic' })
    .attr({ 'text-anchor': anchor || 'middle' })
    .fill(fill)
    .move(x, y - size / 2);
  // arrow over the glyph
  var bb = t.bbox();
  var gw = Math.max(10, size * 0.62);
  var ax2 = bb.x + gw, ax1 = bb.x - 2, ay = bb.y - 4;
  g.line(ax1, ay, ax2, ay).stroke({ color: fill, width: 1.1 });
  g.polygon([[ax2, ay], [ax2 - 4.5, ay - 2], [ax2 - 4.5, ay + 2]]).fill(fill);
  return g;
}
function woodSquare(parent, cx, top, s) {
  var g = parent.group();
  g.rect(s, s).move(cx - s / 2, top).fill('#f8dfa9').stroke({ color: '#b39c70', width: 1.5 });
  var rows = [0.22, 0.42, 0.62, 0.82];
  for (var i = 0; i < rows.length; i++) {
    var y = top + s * rows[i], x = cx - s / 2;
    g.path('M ' + x + ' ' + y +
      ' q ' + (s * 0.25) + ' ' + (-2.5) + ' ' + (s * 0.5) + ' 0' +
      ' q ' + (s * 0.25) + ' ' + (2.5) + ' ' + (s * 0.5) + ' 0')
      .fill('none').stroke({ color: '#ddbd8a', width: 1.1, opacity: 0.85 });
  }
  return g;
}

/* ── Ceiling beam & mount ──────────────────────────────────────────────── */
var beamG = draw.group();
var beamRect = beamG.rect(345, 22).move(0, 0).fill('#f7e8c5').stroke({ color: '#d8c79c', width: 1.5 });
var plate = beamG.rect(80, 7).move(130, 22).fill('#d0d0d0').stroke({ color: '#9d9d9d', width: 1 });
beamG.circle(8).center(145, 25.5).fill('#a5a5a5').stroke({ color: '#7f7f7f', width: 1 });
beamG.circle(8).center(195, 25.5).fill('#a5a5a5').stroke({ color: '#7f7f7f', width: 1 });
interactive(beamRect, 'Support beam', 'Support beam',
  'The pulley hangs from a rigid support. The support carries the total load, but the blocks hang freely from the string.');

/* ── Pulley wheel with yoke, groove & hub ──────────────────────────────── */
var pulleyG = draw.group();
// yoke / bracket arms from the plate down around the wheel
pulleyG.path('M ' + (PCX - 11) + ' 29 L ' + (PCX - 11) + ' ' + (PCY - PR + 18) +
  ' L ' + (PCX + 11) + ' ' + (PCY - PR + 18) + ' L ' + (PCX + 11) + ' 29')
  .fill('#e1e1e1').stroke({ color: '#9a9a9a', width: 1.5 });
// outer wheel
pulleyG.circle(PR * 2).center(PCX, PCY).fill('#a9a9a9').stroke({ color: '#6c6c6c', width: 2 });
// darker rim groove where the cord rides
pulleyG.circle((PR - 3) * 2).center(PCX, PCY).fill('none').stroke({ color: '#5f5f5f', width: 4 });
// spinning face
var spinG = pulleyG.group();
spinG.circle((PR - 8) * 2).center(PCX, PCY).fill('#c9c9c9').stroke({ color: '#878787', width: 1.5 });
for (var a = 0; a < 4; a++) {
  var ang = (15 + a * 90) * Math.PI / 180, rOut = PR - 12;
  spinG.line(PCX, PCY, PCX + Math.cos(ang) * rOut, PCY + Math.sin(ang) * rOut)
    .stroke({ color: '#8a8a8a', width: 3, linecap: 'round' });
}
// hub: collar + axle pin
pulleyG.circle(26).center(PCX, PCY).fill('#8d8d8d').stroke({ color: '#5d5d5d', width: 1.5 });
pulleyG.circle(13).center(PCX, PCY).fill('#b5b5b5').stroke({ color: '#666', width: 1 });
pulleyG.circle(6).center(PCX, PCY).fill('#4f4f4f');
interactive(pulleyG, 'Pulley — frictionless', 'Frictionless pulley',
  'The pulley is massless and frictionless, so it only redirects the string: the tension is identical on both sides. The cord rides in the rim groove and the spokes turn as the string slides over it.');

/* ── Cord & hanging blocks ─────────────────────────────────────────────── */
var cord = draw.path('').fill('none').stroke({ color: CORDC, width: 4.5, linecap: 'round' });
interactive(cord, 'One continuous string', 'One string, one tension',
  'A single unbroken string joins the two blocks over the pulley. Because it is one string, the tension T is the same everywhere along it.');

var b1G = draw.group();
woodSquare(b1G, CX1, 0, BLOCK);
labelText(b1G, 'm₁', CX1 - BLOCK / 2 - 22, BLOCK / 2, 'end', 16);
interactive(b1G, 'Block m₁ (lighter)', 'Block m₁',
  'The string tension pulls m₁ up while its own weight pulls it down. Because m₂ is heavier, m₁ accelerates upward with the same magnitude as m₂ descends.');

var b2G = draw.group();
woodSquare(b2G, CX2, 0, BLOCK);
labelText(b2G, 'm₂', CX2 + BLOCK / 2 + 22, BLOCK / 2, 'start', 16);
interactive(b2G, 'Block m₂ (heavier)', 'Block m₂',
  'The heavier block descends: its weight exceeds the tension, so the net force points down. The string forces the same-sized acceleration on both blocks.');
b2G.on('mousemove', function (e) { showTooltip('Block m₂ = ' + m2Mass + ' kg', e); });

/* ── Free-body diagrams (static squares & headings) ────────────────────── */
var fbdStatic = draw.group();
fbdStatic.text('Block 1').move(FBX1, 8).attr('text-anchor', 'middle').font({ size: 15, family: 'sans-serif' }).fill('#2a2a2a');
fbdStatic.text('Block 2').move(FBX2, 8).attr('text-anchor', 'middle').font({ size: 15, family: 'sans-serif' }).fill('#2a2a2a');
woodSquare(fbdStatic, FBX1, FBCY - FBS / 2, FBS);
woodSquare(fbdStatic, FBX2, FBCY - FBS / 2, FBS);
labelText(fbdStatic, 'm₁', FBX1 - FBS / 2 - 12, FBCY, 'end', 15);
labelText(fbdStatic, 'm₂', FBX2 - FBS / 2 - 12, FBCY, 'end', 15);

var fbdArrowG = draw.group();
var accelG = draw.group();

/* ── Geometry update ───────────────────────────────────────────────────── */
function render() {
  var top1 = BASE1 - offset, top2 = BASE2 + offset;
  b1G.transform({ translate: [0, top1] });
  b2G.transform({ translate: [0, top2] });
  cord.attr('d',
    'M ' + CX1 + ' ' + top1 +
    ' L ' + CX1 + ' ' + PCY +
    ' A ' + PR + ' ' + PR + ' 0 0 1 ' + CX2 + ' ' + PCY +
    ' L ' + CX2 + ' ' + top2);
  spinG.transform({ rotate: offset / PR * 180 / Math.PI, cx: PCX, cy: PCY });
}

/* ── Rebuild free-body arrows (equal T, weights track masses) ──────────── */
function rebuildFbd() {
  fbdArrowG.clear();
  var data = [
    { x: FBX1, m: M1, sub: '₁' },
    { x: FBX2, m: m2Mass, sub: '₂' }
  ];
  for (var i = 0; i < data.length; i++) {
    var bx = data[i].x;
    // tension: from the block centre up through the top edge
    var tAr = makeArrow(fbdArrowG, bx, FBCY, bx, FBCY - FBS / 2 - 58, RED, 3.2);
    vectorLabel(fbdArrowG, 'T', null, bx - 16, FBCY - FBS / 2 - 30, 'end', 15);
    interactive(tAr, 'Tension T — equal for both blocks', 'Equal tensions',
      'Both free-body diagrams show the same tension arrow. One continuous string carries one tension to both blocks — it never differs between them.');
    // weight: from the block centre down through the bottom edge
    var wLen = 30 * data[i].m;
    var wAr = makeArrow(fbdArrowG, bx, FBCY, bx, FBCY + FBS / 2 + wLen, RED, 3.2);
    vectorLabel(fbdArrowG, 'w', data[i].sub, bx - 16, FBCY + FBS / 2 + wLen / 2, 'end', 15);
    interactive(wAr, 'Weight w' + data[i].sub + ' = m·g', 'Weights drive the motion',
      'Weight is proportional to mass. The difference between the two weights is the net driving force: acceleration is (m₂−m₁)/(m₂+m₁)·g.');
  }
}

/* ── Rebuild acceleration arrows on the main blocks ────────────────────── */
function rebuildAccel() {
  accelG.clear();
  if (releaseState === 'held') return;
  var a = aMag();
  if (a < 1e-9) return; // balanced masses: no acceleration
  var len = 90 * a;
  var top1 = BASE1 - offset, top2 = BASE2 + offset;
  var x1 = CX1 - BLOCK / 2 - 14, x2 = CX2 + BLOCK / 2 + 14;
  var g1 = makeArrow(accelG, x1, top1 + BLOCK / 2, x1, top1 + BLOCK / 2 - len, GREEN, 3);
  var g2 = makeArrow(accelG, x2, top2 + BLOCK / 2, x2, top2 + BLOCK / 2 + len, GREEN, 3);
  vectorLabel(accelG, 'a', null, x1 + 10, top1 + BLOCK / 2 - len, 'start', 13, GREEN);
  vectorLabel(accelG, 'a', null, x2 - 10, top2 + BLOCK / 2 + len, 'end', 13, GREEN);
  var txt = 'Accelerations: equal size, opposite directions';
  var body = 'The string cannot stretch, so the two blocks move by the same distance in the same time. Their accelerations share one magnitude and point opposite ways.';
  interactive(g1, txt, 'One acceleration magnitude', body);
  interactive(g2, txt, 'One acceleration magnitude', body);
}

/* ── Animation: constant acceleration, one direction, clamps at limits ── */
function tick(now) {
  if (releaseState !== 'moving') { animId = null; return; }
  var dt = Math.min(0.05, (now - lastT) / 1000);
  lastT = now;
  var a = aMag();
  if (a < 1e-9) {
    // balanced: nothing moves
    render();
    animId = requestAnimationFrame(tick);
    return;
  }
  // constant-acceleration kinematics: v += a·dt, x += v·dt (scaled for display)
  vel += a * 260 * dt;
  offset += vel * dt;
  if (offset >= TRAVEL) {
    // travel limit reached (m₁ at the pulley): pause, then reset to start
    offset = TRAVEL;
    render();
    rebuildAccel();
    stopAnim();
    setTimeout(function () {
      if (releaseState !== 'moving') return;
      offset = 0; vel = 0;
      render(); rebuildAccel();
      lastT = performance.now();
      animId = requestAnimationFrame(tick);
    }, 700);
    return;
  }
  render();
  rebuildAccel();
  animId = requestAnimationFrame(tick);
}
function startAnim() { vel = 0; lastT = performance.now(); animId = requestAnimationFrame(tick); }
function stopAnim() { if (animId) { cancelAnimationFrame(animId); animId = null; } }

/* ── Interaction handlers (global, called by inline UI) ────────────────── */
function update_massDifference(v) {
  m2Mass = +v;
  rebuildFbd();
  rebuildAccel();
  updateFormula();
}
function updateFormula() {
  var el = document.getElementById('formulaReadout');
  el.textContent = 'a = (m₂−m₁)/(m₂+m₁)·g ≈ ' + aMag().toFixed(2) + ' g · T equal on both blocks';
}
function trigger_releaseState() {
  var i = STATES.indexOf(releaseState);
  setReleaseState(STATES[(i + 1) % STATES.length]);
}
function setReleaseState(s) {
  releaseState = s;
  var btn = document.getElementById('releaseBtn');
  btn.textContent = s === 'held' ? 'Release the blocks'
    : s === 'released' ? 'Start moving'
    : 'Hold & reset';
  stopAnim();
  if (s === 'held') { offset = 0; vel = 0; render(); }
  rebuildAccel();
  if (s === 'moving') startAnim();
}

/* ── Guided demo steps ─────────────────────────────────────────────────── */
var stepsData = [
  {
    title: 'One string, one tension',
    narration: 'Compare the two free-body diagrams: both tension arrows are identical in length because a single string carries the same tension to both blocks, while w₂ is longer than w₁ because m₂ is heavier.',
    state: { massDifference: 3, releaseState: 'held' }
  },
  {
    title: 'Change the mass difference',
    narration: 'Drag the m₂ slider: the weight arrows and the acceleration arrows resize together, but the two tension arrows remain equal — the mass difference sets how fast the system accelerates, not whether the tensions match.',
    state: { massDifference: 5, releaseState: 'held' }
  },
  {
    title: 'Release and watch the motion',
    narration: 'Step from held to released to moving: m₂ sinks while m₁ rises with constant acceleration, speeding up until m₁ reaches the pulley — the string constraint forces equal-magnitude, opposite-direction accelerations.',
    state: { massDifference: 5, releaseState: 'moving' }
  },
  {
    title: 'Balanced masses',
    narration: 'Set m₂ equal to m₁: the weight arrows match, acceleration drops to zero, and the blocks hang motionless even after release — acceleration comes only from the weight difference.',
    state: { massDifference: 1, releaseState: 'moving' }
  }
];
var stepIndex = 0;
function applyStep(i) {
  stepIndex = Math.max(0, Math.min(stepsData.length - 1, i));
  var s = stepsData[stepIndex];
  var input = document.getElementById('massDifferenceInput');
  input.value = s.state.massDifference;
  document.getElementById('massDifferenceVal').value = s.state.massDifference;
  update_massDifference(+s.state.massDifference);
  setReleaseState(s.state.releaseState);
  document.getElementById('demoNarration').textContent =
    (stepIndex + 1) + '. ' + s.title + ': ' + s.narration;
  document.getElementById('stepLabel').textContent =
    (stepIndex + 1) + '/' + stepsData.length;
}
